import sys,json,hashlib,copy,statistics
from pathlib import Path
W,O=map(Path,sys.argv[1:3])
sys.path[:0]=[str(W/'build/validation/hmd-python-deps'),str(W/'tools/nr-color')]
import numpy as np
from PIL import Image,ImageDraw
import hmd_assess as h
def unwrap(d):
 if 'status' in d and d['status']=='fulfilled':return unwrap(d['value'])
 if 'content' in d:return json.loads(next(x['text'] for x in d['content'] if x['type']=='text'))
 return d
def rd(p):return h.read_json(p)
def receipt(n):return unwrap(rd(O/(n+'.json')))
policy=rd(O/'regions.json'); plan=rd(O/'plan.json')
pre=rd(O/'preflight.json')
base=unwrap(pre['stage0'])['neuralRendering']['requestedConfiguration']
pin=None;refcam=None;refs={};rows=[];seqs=[];errors=[];artifacts=[];exposures=[];private=[]
labels=[x for x in plan['phaseOrder'] if (O/(x+'-terminal.json')).exists()]
for label in labels:
 t=receipt(label+'-terminal'); desc=next(x for x in t['result']['artifacts'] if x['path']==t['result']['manifest']['finalPath'])
 mp=h.committed(desc,O);m=rd(mp)
 assert m['producer']['buildId']=='f7d6c4f8be8279f1380d812125a4dd072346994f330eacdbccf07e653c45403c'
 assert m['sessionId']=='b93d5101-c01b-9d38-2b9b-06507f48de01'
 cfg=receipt(label+'-configure') if (O/(label+'-configure.json')).exists() else unwrap(pre['pre1'])
 if label=='off-return':cfg=receipt('p100-return-configure')
 config=copy.deepcopy(base);config['color']={'settings':cfg['settings'],'experiments':cfg['experiments']}
 config['upscaling']['neuralRenderingEnabled']=not label.startswith('off')
 frames=[];times=[];cams=[];fingerprints=set()
 for ch in m['children']:
  ordinal=ch['ordinal']
  if ch.get('state') not in ['completed','completed_with_warnings']:
   errors.append({'label':label,'ordinal':ordinal,'error':'child not completed','state':ch.get('state')});continue
  a=ch['actual']['acquisition'];e=a['nrEvidence'];camera=a['cameraEvidence']
  if pin is None:pin={p['eye']:p for p in a['planes']}
  if refcam is None:refcam=camera
  drift={k:float(np.max(np.abs(np.array(camera[k])-np.array(refcam[k])))) for k in ['view','projection','positionAdjust']}
  cams.append(drift);frames.append(a['engineFrame']);times.append(a['monotonicTimestampUs']);fingerprints.add(e['configurationFingerprint'])
  expected={'configuration':config,'configurationFingerprint':e['configurationFingerprint'],'colorRevision':cfg['revision'],'inputEpoch':cfg['inputEpoch'][0],'insertion':'upscaled_center','planes':pin,'maximumRenderFrameAge':0}
  condition='nr_off' if label.startswith('off') else 'raw' if label.startswith('raw') else 'managed_identity' if label.startswith('managed') else 'preserve_source'
  candidate={'condition':condition,'applyModelEdit':cfg['experiments']['applyModelEdit'],'settings':{'settings':cfg['settings']}}
  try:
   assert ch['actual']['source']['kind']=='hmd_submission' and ch['actual']['source']['fallback']=='reject'
   assert not ch['actual']['source'].get('fallbackApplied')
   assert e['configuration']==config,'unrequested configuration'
   assert camera['available'] and camera['sourceWorldFrame']==e['left']['sourceWorldFrame']
   if condition!='nr_off':h.check_pair(ch,mp.parent,expected,candidate,policy,sequence=m)
   else:
    # NR disabled retains its colour setting; validate disabled outcomes explicitly.
    assert e['available'] and e['schemaVersion']==1 and e['transactionId']
    for eye in ['left','right']:
     r=e[eye]
     assert r['frame']==r['sourceWorldFrame']==a['engineFrame']
     assert r['colorRevision']==cfg['revision'] and r['inputEpoch']==cfg['inputEpoch'][0]
     assert r['effectiveMode']==cfg['settings']['mode']
     assert not any(r[k] for k in ['nrEnabled','inferenceAttempted','inferenceSucceeded','outputCommitted'])
     assert r['applyModelEdit']==cfg['experiments']['applyModelEdit']
   assert len(a['planes'])==2 and {p['eye']:p for p in a['planes']}==pin
   companions=h.captured_diagnostics(ch)
   assert companions is not None
   exposures.append({'label':label,'ordinal':ordinal,'frame':a['engineFrame'],'evidence':companions['exposures'],'requests':companions['measurementRequests']})
   for batch in companions['measurementBatches']:
    for mm in batch['measurements']:
     s=mm['source'];v=mm['values']
     assert s['sourceWorldFrame']==e['left']['sourceWorldFrame'] and s['revision']==cfg['revision']
     private.append({'label':label,'ordinal':ordinal,'eye':'left' if s['physicalSlot']%2==0 else 'right','frame':s['frame'],'lightingPreservation':s['lightingPreservation'],'signedRGB':[v[i+4]-v[i] for i in range(3)],'meanAbsoluteDelta':v[7],'nonfinite':v[12:15],'shown':s['modelEditShown']})
  except Exception as ex:errors.append({'label':label,'ordinal':ordinal,'error':str(ex)})
  for eye in ['left','right']:
   aa=[x for x in ch['artifacts'] if x.get('actual',{}).get('view')==eye+'_eye']
   assert len(aa)==1
   art=aa[0];p=h.committed(art,mp.parent)
   assert art['actual']['format']=='png' and art['actual']['colourContract']=='sdr_srgb'
   artifacts.append({'label':label,'ordinal':ordinal,'eye':eye,**art})
   with Image.open(p) as im:
    assert im.size==(2468,2740) and im.format=='PNG'
    im.load()
    for region in policy['eyes'][eye]['regions']:
     x,y,w,hh=region['rect'];crop=im.crop((x,y,x+w,y+hh));pixels=np.asarray(crop)[...,:3]
     key=(eye,region['id'])
     if key not in refs:refs[key]=pixels.copy()
     metrics=h.compare_pixels(pixels,refs[key])
     rows.append({'label':label,'eye':eye,'region':region['id'],'ordinal':ordinal,'frame':a['engineFrame'],**metrics})
     if ordinal in [1,6,12]:
      cp=O/'crops'/f'{label}-{eye}-{region["id"]}-{ordinal}.png';cp.parent.mkdir(exist_ok=True);crop.save(cp)
 assert len(fingerprints)==1
 seqs.append({'label':label,'manifest':desc,'counts':m['counts'],'frames':frames,'timestampsUs':times,'spacingMs':(np.diff(times)/1000).tolist(),'cameraMaxDrift':{k:max(c[k] for c in cams) for k in cams[0]},'fingerprint':next(iter(fingerprints))})
 print(label,'analysed',len(frames),'pairs',flush=True)
metrics=[k for k in rows[0] if k not in ['label','eye','region','ordinal','frame']]
means=[];temporal=[]
for label in labels:
 for eye in ['left','right']:
  for region in policy['eyes'][eye]['regions']:
   rr=[r for r in rows if (r['label'],r['eye'],r['region'])==(label,eye,region['id'])]
   means.append({'label':label,'eye':eye,'region':region['id'],**{k:float(np.mean([r[k] for r in rr])) for k in metrics}})
   temporal.append({'label':label,'eye':eye,'region':region['id'],**{k:{'min':min(r[k] for r in rr),'max':max(r[k] for r in rr),'std':float(np.std([r[k] for r in rr])),'maxSuccessiveDelta':float(np.max(np.abs(np.diff([r[k] for r in rr]))))} for k in ['luma_mean','mean_r','mean_g','mean_b','edge_rms','local_contrast']}})
baseline=[]
for eye in ['left','right']:
 for region in policy['eyes'][eye]['regions']:
  rr=[r for r in means if r['label'].startswith('off') and (r['eye'],r['region'])==(eye,region['id'])]
  baseline.append({'eye':eye,'region':region['id'],**{k:{'min':min(r[k] for r in rr),'max':max(r[k] for r in rr),'range':max(r[k] for r in rr)-min(r[k] for r in rr)} for k in metrics}})
stereo=[]
for label in labels:
 for region in policy['eyes']['left']['regions']:
  rr={e:next(r for r in means if (r['label'],r['eye'],r['region'])==(label,e,region['id'])) for e in ['left','right']}
  stereo.append({'label':label,'region':region['id'],**{k:rr['left'][k]-rr['right'][k] for k in ['delta_luma_mean','delta_mean_r','delta_mean_g','delta_mean_b','delta_edge_rms']}})
for eye in ['left','right']:
 for reg in ['face-a','face-b','armour-a','cloth-b','floor']:
  rect=next(r['rect'] for r in policy['eyes'][eye]['regions'] if r['id']==reg)
  ww,hh=rect[2:];sheet=Image.new('RGB',(max(ww,190)*len(labels),hh+30),(225,225,225));draw=ImageDraw.Draw(sheet)
  for col,label in enumerate(labels):
   with Image.open(O/'crops'/f'{label}-{eye}-{reg}-6.png') as im:sheet.paste(im,(col*max(ww,190),30))
   draw.text((col*max(ww,190)+3,4),label,fill='black')
  # Split sheets into short unscaled panels to keep native crops readable.
  for col in range(0,len(labels),5):sheet.crop((col*max(ww,190),0,min((col+5)*max(ww,190),sheet.width),sheet.height)).save(O/f'contact-{eye}-{reg}-{col//5}.png')
 if len(labels)>3:
  for label in ['off-a','p100-forward','p0-forward','p100-return','off-return']:
   if label not in labels:continue
   sheet=Image.new('RGB',(3*200,400),(225,225,225));draw=ImageDraw.Draw(sheet)
   for ri,reg in enumerate(['face-a','face-b']):
    for ci,n in enumerate([1,6,12]):
     with Image.open(O/'crops'/f'{label}-{eye}-{reg}-{n}.png') as im:sheet.paste(im,(ci*200,ri*200+24))
     draw.text((ci*200,ri*200),f'{reg} frame {n}',fill='black')
   sheet.save(O/f'temporal-{eye}-{label}.png')
result=O/'results';result.mkdir(exist_ok=True)
for n,data in [('regions',rows),('sequences',seqs),('means',means),('baseline',baseline),('temporal',temporal),('stereo',stereo),('artifacts',artifacts),('attribution-errors',errors),('exposures',exposures),('private',private)]:
 h.save_json(result/(n+'.json'),data)
h.write_csv(result/'regions.csv',rows)
summary={'pairs':len(artifacts)//2,'sequences':len(seqs),'errors':errors,'baselineSequences':[r['label'] for r in seqs if r['label'].startswith('off')],'cadenceMsRange':[min(x for r in seqs for x in r['spacingMs']),max(x for r in seqs for x in r['spacingMs'])],'maxCameraDrift':{k:max(r['cameraMaxDrift'][k] for r in seqs) for k in seqs[0]['cameraMaxDrift']},'analyserSHA256':h.digest(W/'tools/nr-color/hmd_assess.py'),'scriptSHA256':h.digest(Path(__file__)),'regionsSHA256':h.digest(O/'regions.json'),'planSHA256':h.digest(O/'plan.json'),'versions':{'numpy':np.__version__,'Pillow':Image.__version__},'userOverrides':plan['userOverrides'],'untested':plan['untestedConditions']}
h.save_json(result/'summary.json',summary)
print(json.dumps(summary,indent=2))

