import json,sys,hashlib
from pathlib import Path
from statistics import mean
W,O=map(Path,sys.argv[1:3]);sys.path[:0]=[str(W/'build/validation/hmd-python-deps'),str(W/'tools/nr-color')]
import hmd_assess as h
from PIL import Image,ImageDraw
R=O/'results'; rows=h.read_json(R/'means.json'); baseline=h.read_json(R/'baseline.json'); temporal=h.read_json(R/'temporal.json'); seqs=h.read_json(R/'sequences.json')
def one(label,eye,region):return next(r for r in rows if (r['label'],r['eye'],r['region'])==(label,eye,region))
def off(eye,region,key):return mean(r[key] for r in rows if r['label'].startswith('off') and (r['eye'],r['region'])==(eye,region))
labels=h.read_json(O/'plan.json')['phaseOrder'];regs=[r['id'] for r in h.read_json(O/'regions.json')['eyes']['left']['regions']]
effects=[];stereo=[]
for label in labels:
 for region in regs:
  ey={}
  for eye in ['left','right']:
   r=one(label,eye,region)
   d={k:r[k]-off(eye,region,k) for k in ['luma_mean','mean_r','mean_g','mean_b','edge_rms','local_contrast','near_black_fraction','near_white_fraction','clipped_white_fraction']}
   effects.append({'label':label,'eye':eye,'region':region,'deltaFromMeanOff':d});ey[eye]=d
  stereo.append({'label':label,'region':region,'leftMinusRightAfterSeparateReferenceSubtraction':{k:ey['left'][k]-ey['right'][k] for k in ey['left']}})
excluded=[]
for s in seqs:
 for i,frame in enumerate(s['frames']):
  if 341124<=frame<347978:
   for eye in ['left','right']:excluded.append({'label':s['label'],'ordinal':i+1,'eye':eye,'region':'shadow','reason':'OBody CustomMenu overlays fixed wall-shadow region; character/material regions remain visible'})
h.save_json(R/'regional-exclusions.json',excluded)
h.save_json(R/'source-relative-effects.json',effects)
h.save_json(R/'source-relative-stereo.json',stereo)
exp=h.read_json(R/'exposures.json');priv=h.read_json(R/'private.json')
expsummary={'capturedPairs':len(exp),'availableExposureCompanions':sum(e['available'] for x in exp for e in x['evidence']),'scalarStatuses':sorted({e['evidence']['scalarStatus'] for x in exp for e in x['evidence'] if e['available']}),'frameGammaExponents':sorted({e['evidence']['frameGammaExponent'] for x in exp for e in x['evidence'] if e['available']}),'privateEyeMeasurements':len(priv),'nonfiniteTotals':sum(sum(x['nonfinite']) for x in priv)}
h.save_json(R/'exposure-summary.json',expsummary)
p100=[r for r in effects if r['label'].startswith('p100') and r['region'] in ['face-a','face-b']]
st=[r for r in stereo if r['label'].startswith('p100') and r['region'] in ['face-a','face-b']]
key={'maxAbsoluteFaceMeanLumaShiftP100':max(abs(r['deltaFromMeanOff']['luma_mean']) for r in p100),'maxAbsoluteFaceMeanRGBShiftP100':max(abs(r['deltaFromMeanOff'][k]) for r in p100 for k in ['mean_r','mean_g','mean_b']),'maxStereoFaceMeanLumaDifferenceP100':max(abs(r['leftMinusRightAfterSeparateReferenceSubtraction']['luma_mean']) for r in st),'exclusions':len(excluded),'exposure':expsummary}
for reg in ['face-a','face-b']:
 for group in ['off','p100']:
  rr=[r for r in temporal if r['region']==reg and r['label'].startswith(group)]
  key[group+'_'+reg+'_temporalLumaStdRange']=[min(r['luma_mean']['std'] for r in rr),max(r['luma_mean']['std'] for r in rr)]
h.save_json(R/'key-findings.json',key)
# Full twelve-frame native face crops for the primary shown/source comparison.
for eye in ['left','right']:
 for label in ['off-c','p100-forward','hidden-b','p100-return']:
  m=h.read_json(next((O/label).glob('*/sequence.json')))
  for reg in ['face-a','face-b']:
   r=next(r for r in h.read_json(O/'regions.json')['eyes'][eye]['regions'] if r['id']==reg);x,y,w,hh=r['rect']
   sheet=Image.new('RGB',(6*w,2*(hh+22)),(230,230,230));draw=ImageDraw.Draw(sheet)
   for i,ch in enumerate(m['children']):
    art=next(a for a in ch['artifacts'] if a['actual']['view']==eye+'_eye')
    with Image.open(art['path']) as im:sheet.paste(im.crop((x,y,x+w,y+hh)),(i%6*w,i//6*(hh+22)+22))
    draw.text((i%6*w,i//6*(hh+22)),str(ch['ordinal']),fill='black')
   sheet.save(O/f'allframes-{eye}-{label}-{reg}.png')
# Source versus visible NR detail comparisons in identical unscaled regions.
for eye in ['left','right']:
 for reg in ['floor','armour-a','cloth-b']:
  selected=['off-return','hidden-b','p100-return','p50-forward','p0-forward']
  ims=[Image.open(O/'crops'/f'{l}-{eye}-{reg}-6.png') for l in selected]
  w=max(im.width for im in ims);hh=max(im.height for im in ims);sheet=Image.new('RGB',(5*max(w,180),hh+30),(230,230,230));d=ImageDraw.Draw(sheet)
  for i,(label,im) in enumerate(zip(selected,ims)):
   sheet.paste(im,(i*max(w,180),30));d.text((i*max(w,180),5),label,fill='black');im.close()
  sheet.save(O/f'detail-{eye}-{reg}.png')
print(json.dumps(key,indent=2))
